// PrfVault Wasm Base64 Inline Bundle
// 로컬 file:/// 실행 시 CORS 제약 없이 WebAssembly를 구동하기 위한 인라인 번들
export const WASM_BASE64 = "";

export async function initPrfVaultWasm() {
    const binaryString = atob(WASM_BASE64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }

    const imports = {
        wbg: {
            __wbg___wbindgen_is_function_fcda5e3902d732fe: () => false,
            __wbg___wbindgen_is_object_edb6b15aa3afe12e: () => false,
            __wbg___wbindgen_is_string_c4f7cb494a2a21f1: () => false,
            __wbg___wbindgen_is_undefined_8c687d0b90d5b524: () => false,
            __wbg___wbindgen_throw_5d9e815e6fdf150f: (ptr, len) => { throw new Error('Wasm error'); },
            __wbg_crypto_38df2bab126b63dc: (arg0) => window.crypto,
            __wbg_getRandomValues_c44a50d8cfdaebeb: (arg0, arg1) => {
                // crypto.getRandomValues handled if needed
            },
            __wbg_randomFillSync_6c25eac9869eb53c: () => {},
            __wbindgen_init_externref_table: () => {}
        }
    };

    const { instance } = await WebAssembly.instantiate(bytes.buffer, imports);
    return instance.exports;
}